    :root {
      --primary: #EB0028;
      --foreground: #121212;
      --background: #FFFFFF;
      --muted: #444444;
      --link: #777777;
      --border: #E5E5E5;
      --radius: 0.5rem;
    }

    * {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
    }

    body {
      font-family: 'Inter', system-ui, -apple-system, sans-serif;
      background-color: var(--background);
      color: var(--foreground);
      line-height: 1.6;
      min-height: 100vh;
      display: flex;
      flex-direction: column;
    }

    main {
      flex: 1;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      padding: 2rem 1.5rem;
    }

    /* Logo */
    .logo {
      margin-bottom: 3rem;
    }

    .logo-text {
      font-size: 2rem;
      font-weight: 700;
      letter-spacing: -0.02em;
      display: flex;
      align-items: center;
      gap: 0;
    }

    .logo-idea {
      color: var(--foreground);
    }

    .logo-forum {
      color: var(--primary);
    }

    .logo-e-missing {
      color: var(--link);
      opacity: 0.5;
    }

    /* Error Content */
    .error-content {
      text-align: center;
      max-width: 480px;
      width: 100%;
    }

    .error-message {
      font-size: 1.5rem;
      font-weight: 600;
      color: var(--foreground);
      margin-bottom: 0.75rem;
    }

    .error-suggestion {
      font-size: 1rem;
      color: var(--muted);
      margin-bottom: 2rem;
    }

    /* Search */
    .search-form {
      margin-bottom: 2rem;
    }

    .search-wrapper {
      position: relative;
      display: flex;
      max-width: 400px;
      margin: 0 auto;
    }

    .search-input {
      width: 100%;
      padding: 0.875rem 3rem 0.875rem 1rem;
      font-size: 1rem;
      font-family: inherit;
      border: 1px solid var(--border);
      border-radius: var(--radius);
      background: var(--background);
      color: var(--foreground);
      transition: border-color 150ms ease, box-shadow 150ms ease;
    }

    .search-input::placeholder {
      color: var(--link);
    }

    .search-input:focus {
      outline: none;
      border-color: var(--primary);
      box-shadow: 0 0 0 3px rgba(235, 0, 40, 0.1);
    }

    .search-btn {
      position: absolute;
      right: 0.75rem;
      top: 50%;
      transform: translateY(-50%);
      background: none;
      border: none;
      cursor: pointer;
      padding: 0.25rem;
      color: var(--link);
      transition: color 150ms ease;
    }

    .search-btn:hover {
      color: var(--primary);
    }

    .search-btn svg {
      width: 1.25rem;
      height: 1.25rem;
    }

    /* Error Code Bar */
    .error-code-bar {
      background: #F5F5F5;
      padding: 0.75rem 1.5rem;
      border-radius: var(--radius);
      margin-bottom: 2rem;
      display: inline-block;
    }

    .error-code-text {
      font-size: 0.875rem;
      font-weight: 500;
      color: var(--muted);
    }

    /* Divider */
    .divider {
      width: 60px;
      height: 1px;
      background: var(--border);
      margin: 0 auto 2rem;
    }

    /* Next Steps */
    .next-steps {
      margin-bottom: 2rem;
    }

    .next-steps-heading {
      font-size: 0.875rem;
      font-weight: 600;
      color: var(--foreground);
      margin-bottom: 1rem;
      text-transform: uppercase;
      letter-spacing: 0.05em;
    }

    .next-steps-links {
      display: flex;
      flex-direction: column;
      gap: 0.75rem;
    }

    .nav-link {
      font-size: 1rem;
      color: var(--link);
      text-decoration: none;
      transition: color 150ms ease, text-decoration 150ms ease;
      display: inline-block;
    }

    .nav-link:hover {
      color: var(--primary);
      text-decoration: underline;
    }

    /* Cookie Banner */
    .cookie-banner {
      position: fixed;
      bottom: 0;
      left: 0;
      right: 0;
      background: var(--foreground);
      color: var(--background);
      padding: 1rem 1.5rem;
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      justify-content: center;
      gap: 0.5rem 1rem;
      font-size: 0.875rem;
      z-index: 100;
    }

    .cookie-banner-text {
      text-align: center;
      max-width: 700px;
    }

    .cookie-banner a {
      color: var(--background);
      opacity: 0.8;
    }

    .cookie-banner a:hover {
      opacity: 1;
      text-decoration: underline;
    }

    .cookie-prefs-btn {
      background: transparent;
      border: 1px solid rgba(255, 255, 255, 0.4);
      color: var(--background);
      padding: 0.5rem 1rem;
      font-size: 0.875rem;
      font-family: inherit;
      border-radius: var(--radius);
      cursor: pointer;
      transition: background 150ms ease, border-color 150ms ease;
      white-space: nowrap;
    }

    .cookie-prefs-btn:hover {
      background: rgba(255, 255, 255, 0.1);
      border-color: rgba(255, 255, 255, 0.6);
    }

    /* Cookie Preferences Modal */
    .modal-overlay {
      position: fixed;
      inset: 0;
      background: rgba(0, 0, 0, 0.5);
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 1rem;
      z-index: 200;
      opacity: 0;
      visibility: hidden;
      transition: opacity 200ms ease, visibility 200ms ease;
